function decodeUploadFilename(value:unknown){const filename=clean(value);if(!/[\u00c0-\u00ff]/.test(filename))return filename;const decoded=Buffer.from(filename,"latin1").toString("utf8");return decoded.includes("\uFFFD")?filename:decoded}
