app.post("/api/analysis-jobs/:id/ai-comparison",async(req,res,next)=>{try{const job=await ownedJob(req);if(!job)return fail(res,"任务不存在",404);const storeIds=[...new Set((Array.isArray(req.body.store_ids)?req.body.store_ids:[]).map(Number))];if(storeIds.length<2||storeIds.length>10)return fail(res,"请选择 2–10 家门店进行 AI 对比");const count=await query("SELECT id FROM stores WHERE tenant_id=$1 AND created_by=$2 AND job_id=$3 AND id=ANY($4::bigint[])",[req.user!.tenantId,req.user!.id,job.id,storeIds]);if(count.rowCount!==storeIds.length)return fail(res,"部分门店不存在或无权访问",403);const result=await enqueueAndWait<Record<string,unknown>>("ai-comparison",{tenantId:req.user!.tenantId,userId:req.user!.id,jobId:Number(job.id),storeIds,radii:job.config_json?.radii||[500]});ok(res,{...result,store_labels:storeIds.map((storeId,index)=>({store_id:storeId,label:`门店${String.fromCharCode(65+index)}`}))},"多店 AI 对比已生成")}catch(error){next(error)}});
app.get("/api/analysis-jobs/:id/ai-comparisons",async(req,res)=>{if(!await ownedJob(req))return fail(res,"任务不存在",404);const rows=(await query<Row>("SELECT * FROM ai_analyses WHERE tenant_id=$1 AND created_by=$2 AND scope='comparison' AND job_id=$3 ORDER BY id DESC LIMIT 30",[req.user!.tenantId,req.user!.id,req.params.id])).rows;ok(res,rows.map(serializeAi))});
app.get("/api/batch-export/options",async(req,res)=>{const jobs=(await query<Row>("SELECT * FROM jobs WHERE tenant_id=$1 AND created_by=$2 ORDER BY id DESC LIMIT 100",[req.user!.tenantId,req.user!.id])).rows;ok(res,{jobs:jobs.map(serializeJob),fields:EXPORT_BASE_FIELDS,required_fields:[{id:"store_name",label:"门店名称"},{id:"store_address",label:"门店地址"}],sheet_options:[{id:"poi_details",label:"POI 明细"},{id:"failures",label:"失败与未完成门店"},{id:"notes",label:"导出说明"}]})});
app.get("/api/ai-exports/activity-template",async(_req,res)=>{const workbook=new ExcelJS.Workbook(),sheet=workbook.addWorksheet("活动差异配置");sheet.addRow(["门店编号","门店名称","门店地址","活动名称","活动目标","活动时间","单店预算","赠品或资源","允许活动形式","备注"]);sheet.addRow(["可选，优先匹配","与导入表一致","与导入表一致","亲子互动日","触达妈妈带孩子家庭","2026-09-15 14:00-17:00","可选","可选","可选","可选"]);const buffer=Buffer.from(await workbook.xlsx.writeBuffer());sendXlsx(res,buffer,"亲子活动差异配置模板.xlsx")});
app.post("/api/ai-exports/activity-preview",upload.single("file"),async(req,res,next)=>{try{if(!req.file)return fail(res,"请选择活动配置表格");const storeIds=[...new Set((JSON.parse(String(req.body.store_ids||"[]")) as unknown[]).map(Number).filter(Number.isInteger))],stores=(await query<Row>("SELECT id,input_name,address,user_code FROM stores WHERE tenant_id=$1 AND created_by=$2 AND id=ANY($3::bigint[])",[req.user!.tenantId,req.user!.id,storeIds])).rows;if(stores.length!==storeIds.length)return fail(res,"部分门店不存在或无权访问",403);const imported=await readImportRows(req.file),overrides:Record<string,unknown>={},matches:unknown[]=[],errors:string[]=[],seen=new Set<number>();for(let index=0;index<imported.length;index++){const row=imported[index],code=clean(row["门店编号"]),name=clean(row["门店名称"]),address=clean(row["门店地址"]),candidates=code?stores.filter(store=>clean(store.user_code)===code):stores.filter(store=>clean(store.input_name)===name&&(!address||clean(store.address)===address));if(candidates.length!==1){errors.push(`第 ${index+2} 行：${candidates.length?"匹配到多个门店":"未匹配到所选门店"}`);continue}const store=candidates[0],id=Number(store.id);if(seen.has(id)){errors.push(`第 ${index+2} 行：门店重复配置`);continue}seen.add(id);const config=normalizeActivityConfig({activity_name:row["活动名称"],objective:row["活动目标"],activity_time:row["活动时间"],budget:row["单店预算"],gifts:row["赠品或资源"],allowed_formats:row["允许活动形式"],notes:row["备注"]}),validated=validateActivityConfig(config);if(validated.errors.length){errors.push(`第 ${index+2} 行：${validated.errors.join("、")}`);continue}overrides[String(id)]=config;matches.push({row:index+2,store_id:id,store_name:store.input_name})}ok(res,{overrides,matches,errors,valid:errors.length===0,total_rows:imported.length})}catch(error){next(error)}});
app.post("/api/ai-exports/preview",async(req,res,next)=>{try{const request=normalizeAiExportRequest({...req.body,user_email:req.user!.email,job_names:[]});ok(res,await previewAiExport(req.user!.tenantId,req.user!.id,request))}catch(error){next(error)}});
