app.post("/api/batch-export",async(req,res,next)=>{try{
  const jobIds:number[]=[...new Set<number>((Array.isArray(req.body.job_ids)?req.body.job_ids:[]).map(Number).filter(Number.isInteger))];
  if(!jobIds.length||jobIds.length>100)return fail(res,"请选择 1–100 个分析任务");
  const jobs=(await query<Row>("SELECT * FROM jobs WHERE tenant_id=$1 AND created_by=$2 AND id=ANY($3::bigint[]) ORDER BY id",[req.user!.tenantId,req.user!.id,jobIds])).rows;
  if(jobs.length!==jobIds.length)return fail(res,"部分任务不存在或无权访问",403);
  const availableRadii:number[]=[...new Set<number>(jobs.flatMap(job=>Array.isArray(job.config_json?.radii)?job.config_json.radii.map(Number):[]))].sort((a,b)=>a-b);
  const availableCategories:string[]=[...new Set<string>(jobs.flatMap(job=>Array.isArray(job.config_json?.categories)?job.config_json.categories.map(String):[]))];
  const radii:number[]=[...new Set<number>((Array.isArray(req.body.radii)?req.body.radii:availableRadii).map(Number))].filter(radius=>availableRadii.includes(radius));
  const categories:string[]=[...new Set<string>((Array.isArray(req.body.categories)?req.body.categories:availableCategories).map(clean))].filter(category=>availableCategories.includes(category));
  if(!radii.length||!categories.length)return fail(res,"所选任务没有可导出的分析半径或 POI 分类");
  const knownFields=new Set<string>(EXPORT_BASE_FIELDS.map(field=>field.id)),fields:string[]=[...new Set<string>((Array.isArray(req.body.fields)?req.body.fields:[]).map(clean))].filter(field=>knownFields.has(field));
  const storeIds:number[]=[...new Set<number>((Array.isArray(req.body.store_ids)?req.body.store_ids:[]).map(Number).filter(Number.isInteger))],params:unknown[]=[req.user!.tenantId,req.user!.id,jobIds],storeClause=storeIds.length?" AND s.id=ANY($4::bigint[])":"",storeParams=storeIds.length?[...params,storeIds]:params;
  const rows=(await query<Row>(`SELECT s.*,j.config_json AS job_config,j.filename AS job_filename FROM stores s JOIN jobs j ON j.id=s.job_id WHERE s.tenant_id=$1 AND s.created_by=$2 AND j.created_by=$2 AND s.job_id=ANY($3::bigint[])${storeClause} ORDER BY s.job_id,s.id`,storeParams)).rows;
  if(storeIds.length&&rows.length!==storeIds.length)return fail(res,"部分门店不存在或无权访问",403);if(!rows.length)return fail(res,"所选任务没有可导出的门店");if(rows.length>5000)return fail(res,"单次最多导出 5,000 家门店");
  const aiRows=(await query<Row>("SELECT DISTINCT ON (store_id) * FROM ai_analyses WHERE tenant_id=$1 AND created_by=$2 AND scope='single' AND store_id=ANY($3::bigint[]) ORDER BY store_id,created_at DESC",[req.user!.tenantId,req.user!.id,rows.map(row=>Number(row.id))])).rows;
  const selection:ExportSelection={jobIds,storeIds,fields,radii,categories,includePoiDetails:Boolean(req.body.include_poi_details),includeFailures:req.body.include_failures!==false,includeNotes:req.body.include_notes!==false},filename=`门店POI批量导出_${new Date().toISOString().slice(0,10)}.xlsx`,buffer=await buildBatchExportWorkbook(rows,aiRows,selection,{userEmail:req.user!.email,jobNames:jobs.map(job=>decodeUploadFilename(job.filename)||`任务#${job.id}`)});
  await audit(req.user!.tenantId,req.user!.id,"batch_export","jobs",jobIds.join(","),ip(req),{store_count:rows.length,radii,categories,fields});sendXlsx(res,buffer,filename);
}catch(error){next(error)}});
