async function ownedJob(req:Request){return (await query<Row>("SELECT * FROM jobs WHERE id=$1 AND tenant_id=$2 AND created_by=$3",[req.params.id,req.user!.tenantId,req.user!.id])).rows[0]}
async function refreshMatchJobSummary(jobId:number,tenantId:number,userId:number){const rows=(await query<{status:string}>("SELECT status FROM stores WHERE job_id=$1 AND tenant_id=$2 AND created_by=$3",[jobId,tenantId,userId])).rows,total=rows.length,matched=rows.filter(row=>["已确认","分析完成","分析失败"].includes(row.status)).length,failed=rows.filter(row=>row.status==="匹配失败").length,review=rows.filter(row=>row.status==="待确认").length,processed=rows.filter(row=>row.status!=="等待匹配").length,status=failed?"匹配部分失败":"匹配完成";await query("UPDATE jobs SET processed_stores=$1,matched_stores=$2,failed_stores=$3,status=$4,control='idle',updated_at=NOW() WHERE id=$5 AND tenant_id=$6 AND created_by=$7",[processed,matched,failed,status,jobId,tenantId,userId]);return {total,matched,failed,review,processed,status}}
function serializeJob(row:Row){const total=Number(row.total_stores||0),stage=row.stage||"match",processed=Number(row.processed_stores||0),stageTotal=stage==="analysis"?Number(row.matched_stores||total):total;return {id:Number(row.id),filename:decodeUploadFilename(row.filename),status:row.status,total_stores:total,processed_stores:processed,matched_stores:Number(row.matched_stores||0),pending_stores:Math.max(0,total-processed),success_stores:Number(row.success_stores||0),failed_stores:Number(row.failed_stores||0),config:row.config_json||{},stage,control:row.control||"idle",stage_total:stageTotal,stage_processed:processed,progress_percent:Math.round(processed/Math.max(1,stageTotal)*100),current_store:row.current_store||"",created_at:new Date(row.created_at).toISOString(),updated_at:new Date(row.updated_at).toISOString()}}
function serializeStore(row:Row){return {id:Number(row.id),input_name:row.input_name,standard_name:row.standard_name,amap_poi_id:row.amap_poi_id,longitude:row.longitude==null?null:Number(row.longitude),latitude:row.latitude==null?null:Number(row.latitude),province:row.province||"",city:row.city||"",district:row.district||"",address:row.address||"",match_score:row.match_score==null?null:Number(row.match_score),match_status:row.match_status||"",match_candidates:Array.isArray(row.match_candidates_json)?row.match_candidates_json:[],confirmation_method:row.confirmation_method||"",location_source:row.amap_poi_id?"高德POI":row.longitude!=null?"用户坐标":"待定位"}}
function serializeAi(row:Row){return {id:Number(row.id),scope:row.scope,job_id:row.job_id==null?null:Number(row.job_id),store_id:row.store_id==null?null:Number(row.store_id),store_ids:row.store_ids_json||[],result:row.result_json||{},model:row.model,prompt_version:row.prompt_version,usage:{input_tokens:Number(row.input_tokens||0),output_tokens:Number(row.output_tokens||0),total_tokens:Number(row.total_tokens||0)},created_at:new Date(row.created_at).toISOString()}}
function sendXlsx(res:Response,buffer:Buffer,filename:string){res.setHeader("Content-Type","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");res.setHeader("Content-Disposition",`attachment; filename="store-poi-export.xlsx"; filename*=UTF-8''${encodeURIComponent(filename)}`);res.setHeader("Access-Control-Expose-Headers","Content-Disposition");res.send(buffer)}
async function exportJob(req:Request,res:Response){const job=await ownedJob(req);if(!job)return fail(res,"任务不存在",404);const params:unknown[]=[req.user!.tenantId,req.user!.id,req.params.id],storeClause=req.params.storeId?" AND s.id=$4":"",rows=(await query<Row>(`SELECT s.*,j.config_json AS job_config,j.filename AS job_filename FROM stores s JOIN jobs j ON j.id=s.job_id WHERE s.tenant_id=$1 AND s.created_by=$2 AND j.created_by=$2 AND s.job_id=$3${storeClause} ORDER BY s.id`,req.params.storeId?[...params,req.params.storeId]:params)).rows;if(!rows.length)return fail(res,"没有可导出的门店",404);const aiRows=(await query<Row>("SELECT DISTINCT ON (store_id) * FROM ai_analyses WHERE tenant_id=$1 AND created_by=$2 AND scope='single' AND store_id=ANY($3::bigint[]) ORDER BY store_id,created_at DESC",[req.user!.tenantId,req.user!.id,rows.map(row=>Number(row.id))])).rows,config=job.config_json||{},selection:ExportSelection={jobIds:[Number(job.id)],storeIds:req.params.storeId?[Number(req.params.storeId)]:[],fields:["city","district","longitude","latitude","status","match_score","poi_total","business_district_type","main_audience","age_ranges","residential_activity_level","residential_activity_index","consumption_level","consumption_index","competitor_total","competitor_same_brand","competitor_other_brand","nearest_competitor","nearest_competitor_distance","competition_level","competition_by_radius","analysis_confidence","ai_summary","ai_confidence","error_message"],radii:Array.isArray(config.radii)?config.radii.map(Number):[500],categories:Array.isArray(config.categories)?config.categories.map(String):[],includePoiDetails:true,includeFailures:true,includeNotes:true},buffer=await buildBatchExportWorkbook(rows,aiRows,selection,{userEmail:req.user!.email,jobNames:[decodeUploadFilename(job.filename)||`任务#${job.id}`]});sendXlsx(res,buffer,req.params.storeId?`门店报告_${rows[0].input_name}.xlsx`:`任务${job.id}_门店POI报告.xlsx`)}

app.use((error:unknown,req:Request,res:Response,next:unknown)=>{void next;req.log.error(error);fail(res,error instanceof Error?error.message:"服务器错误",500,"SERVER_ERROR")});
const port=Number(process.env.API_PORT||8000),server=app.listen(port,"0.0.0.0",()=>console.log(`Node API listening on ${port}`));
async function stop(){server.close();await Promise.allSettled([redis.quit(),taskQueue.close(),pool.end()]);process.exit(0)}process.on("SIGTERM",stop);process.on("SIGINT",stop);
